    public static readonly IReadOnlyList<string> MeasurementFailures = Array.Empty<string>();

    public static double GroundOffsetRatioFor(string englishName, bool back)
    {
        var catalog = back ? BackRatios : FrontRatios;
        return catalog.TryGetValue(englishName, out double ratio) ? ratio : 0;
    }

    public static bool HasMeasurementFor(string englishName, bool back)
    {
        var catalog = back ? BackRatios : FrontRatios;
        return catalog.ContainsKey(englishName);
    }
